<script>import {onMount} from 'svelte';import {snapshot,history,errors,loadResource,request,notify,route} from '../state.js';import {sessionGet,sessionSet,finite,download,csv,bytes} from '../lib.js';import Chart from '../components/Chart.svelte';import Icon from '../components/Icon.svelte';let hours=sessionGet('metrics.hours',6),kind='cluster',node='',nodeSamples=[],loading=false,requestID=0;$: sessionSet('metrics.hours',Number(hours));$: samples=kind==='cluster'?$history:nodeSamples;async function load(force=false){const id=++requestID;loading=true;try{if(kind==='cluster')await loadResource('history',force,Number(hours));else{const r=await request(`history?hours=${hours}&node=${encodeURIComponent(node)}`);if(id!==requestID)return;nodeSamples=r.map(n=>({time:n.last_updated_at,average_latency_ms:n.cql?.ok?n.cql.latency/1e6:null,total_load_bytes:n.load_known?n.load_bytes:null,nodes_healthy:n.state==='healthy'?1:0,cql_healthy:n.cql?.ok?1:0,internode_healthy:n.internode?.ok?1:0}));}}catch(e){notify(e.message,'error');}finally{if(id===requestID)loading=false;}}onMount(()=>{load();const id=setInterval(()=>{if($route==='metrics'&&!loading)load(true);},60000);return ()=>clearInterval(id);});function change(){if(kind!=='cluster'&&!node)node=$snapshot?.nodes[0]?.address||'';load(false);}function exportCSV(){download('scyllascope-metrics.csv',csv(samples,['time','average_latency_ms','total_load_bytes','nodes_healthy','cql_healthy','internode_healthy']),'text/csv;charset=utf-8');}</script>
<section class="panel"><div class="toolbar"><div class="tabs"><button class:active={kind==='cluster'} onclick={()=>{kind='cluster';change();}}>クラスタ集計</button><button class:active={kind==='node'} onclick={()=>{kind='node';change();}}>ノード</button></div>{#if kind==='node'}<select bind:value={node} onchange={change} aria-label="メトリクス対象ノード">{#each ($snapshot?.nodes||[]) as n (n.id)}<option value={n.address}>{n.name}</option>{/each}</select>{/if}<select bind:value={hours} onchange={change} aria-label="履歴の時間範囲"><option value={1}>1時間</option><option value={6}>6時間</option><option value={24}>24時間</option><option value={168}>7日間</option></select><button onclick={()=>load(true)} disabled={loading}><Icon name="refresh" size={14}/>{loading?'取得中':'履歴を更新'}</button><button onclick={exportCSV} disabled={!samples.length}><Icon name="download" size={14}/>CSV</button></div></section>
{#if $errors.history}<p class="notice warning">{$errors.history}</p>{/if}<div class="chart-grid-layout"><section class="panel chart-panel"><Chart {samples} title="CQL OPTIONS 応答時間"/></section><section class="panel chart-panel"><Chart {samples} field="nodes_healthy" title="正常ノード数" unit="台"/></section><section class="panel chart-panel"><Chart {samples} field="cql_healthy" title="CQL応答あり" unit="台"/></section><section class="panel chart-panel"><Chart {samples} field="internode_healthy" title="ノード間TCP 到達数" unit="台"/></section></div>
<p class="hint">SQLiteに保存した観測履歴 · {samples.length} サンプル。範囲はサーバーの保存期間内で指定してください。欠測区間は線をつなぎません。再起動や単一ノードからの結果を、クエリ性能・複製正常性として扱わない設計です。</p>
<section class="panel"><header class="panel-header"><h2>Scylla内部の最新メトリクス</h2><span class="quiet">各ノードを選択して詳細</span></header><div class="metric-summary">{#each ($snapshot?.nodes||[]) as n (n.id)}<div><h3>{n.name}</h3><dl class="definition"><dt>実行中のCompaction</dt><dd>{n.metric_values?.scylla_compaction_manager_compactions??'—'}</dd><dt>保留中のCompaction</dt><dd>{n.metric_values?.scylla_compaction_manager_pending_compactions??'—'}</dd><dt>Read timeouts（累積）</dt><dd>{n.metric_values?.scylla_storage_proxy_coordinator_read_timeouts??'—'}</dd><dt>Write timeouts（累積）</dt><dd>{n.metric_values?.scylla_storage_proxy_coordinator_write_timeouts??'—'}</dd></dl></div>{/each}</div></section>
